function SumEvenElementsAtOddIndices(lst: seq<int>): int
    reads lst
    requires |lst| > 0
{
    var sum := 0;
    var n := |lst|;
    var i := 1; // start from the first odd index
    while i < n
        invariant 0 <= i <= n
        invariant sum == SumEvenElementsAtOddIndices(lst[..i])
    {
        if lst[i] % 2 == 0 {
            sum := sum + lst[i];
        }
        i := i + 2; // move to the next odd index
    }
    return sum;
}
